double MergeMedian(int[] a, int[] b) {
    int total = a.Length + b.Length, i = 0, j = 0, prev = 0, cur = 0;
    for (int step = 0; step <= total / 2; step++) {   // до середины
        prev = cur;
        if (j == b.Length || (i < a.Length && a[i] <= b[j])) cur = a[i++];
        else cur = b[j++];
    }
    return total % 2 == 1 ? cur : (prev + (long)cur) / 2.0;
}

